import {ironCandidates,freshIronTrials,chooseIronTrial,predictIronTrial,beginIronTrial,finishIronTrial,restoreIronTrials} from './iron-affinity-model.js';
import {specimenArt} from './oxygen-affinity.js';
const storageKey='lost-forge-iron-affinity-v1';
export function resetIronAffinity(){try{localStorage.removeItem(storageKey);}catch{}}
function sampleDish(id,after){const d=ironCandidates[id],reduced=after&&d.canReduce,powder=reduced?'#637675':'#995735',reagent=reduced?(id==='Cr'?'#697b47':id==='C'?'#68756a':'#dddcc9'):d.colour;return `<svg viewBox="0 0 280 150" role="img" aria-label="${after?(reduced?'灰黑色鐵與反應產物':'仍有紅棕色氧化鐵，沒有得到金屬鐵'):'紅棕色氧化鐵與'+d.name+'，加熱前'}"><defs><linearGradient id="dish-${id}-${after}" x2="0" y2="1"><stop stop-color="#fffef1"/><stop offset=".5" stop-color="#e4e9db"/><stop offset="1" stop-color="#a3b6af"/></linearGradient></defs><ellipse cx="141" cy="132" rx="103" ry="10" fill="#385c4920"/><path d="M31 79Q43 134 140 136Q237 134 249 79Z" fill="url(#dish-${id}-${after})" stroke="#91a79a"/><ellipse cx="140" cy="79" rx="109" ry="34" fill="#edf0df" stroke="#8fa89c"/><ellipse cx="140" cy="82" rx="98" ry="27" fill="${powder}"/>${Array.from({length:95},(_,i)=>{const angle=i*2.3999,r=Math.sqrt((i+1)/96),x=140+Math.cos(angle)*94*r,y=82+Math.sin(angle)*24*r;return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${1.3+i%3*.8}" fill="${i%3?powder:reagent}" stroke="#ffffff25" stroke-width=".5"/>`;}).join('')}<path d="M36 77Q140 128 244 77" fill="none" stroke="#ffffed" stroke-width="3" opacity=".8"/>${reduced&&id==='C'?'<path d="M124 45q-10-14 2-26m16 25q-5-18 7-30m10 30q11-13 2-24" stroke="#91a493" fill="none" stroke-width="2" opacity=".6"/><text x="140" y="13" text-anchor="middle" fill="#627a68" font-size="10">CO₂ · 無色氣體，箭頭示意</text>':''}</svg>`;}
export function mountIronAffinity(root,ctx){let raw=null;try{raw=JSON.parse(localStorage.getItem(storageKey)||'null');}catch{}let state=restoreIronTrials(raw,Object.keys(ironCandidates).filter(id=>ctx.has('iron-'+id))),alive=true,runId=0;
 const save=()=>{try{localStorage.setItem(storageKey,JSON.stringify({selected:state.selected,predictions:state.predictions}));}catch{}};
 function render(){const id=state.selected,d=ironCandidates[id],done=state.phase==='done',running=state.phase==='running',prediction=state.predictions[id],correct=prediction===d.canReduce;
 root.innerHTML=`<section class="iron-affinity-workshop" data-trial-phase="${state.phase}" aria-label="六種材料還原氧化鐵的預測實驗"><header><div><small>03 / 先挑幫手</small><h3>誰能拿走氧化鐵的氧？</h3></div><b>${Object.keys(state.results).length} / 6 已觀察</b></header>
 <div class="iron-affinity-principle"><div><b>對氧活性較大的元素</b><p>較容易得到氧，自己被氧化，能從合適的金屬氧化物帶走氧。</p></div><span>氧轉移 →</span><div><b>活性較小金屬的氧化物</b><p>可能把氧交出去，失氧被還原。交出氧的是氧化物，並非金屬單質。</p></div></div>
 <p class="iron-affinity-instruction">先取一種材料，留下預測，再按加熱，比較氧化鐵有沒有變成金屬鐵。</p>
 <div class="iron-candidate-rack" role="group" aria-label="挑選和氧化鐵比較的材料">${Object.entries(ironCandidates).map(([k,v])=>`<button type="button" data-iron-candidate="${k}" aria-pressed="${k===id}" ${running?'disabled':''}>${specimenArt(k)}<b>${k} <span>${v.name}</span></b><small>${state.results[k]?'✓ 已觀察':'先預測'}</small></button>`).join('')}</div>
 <div class="iron-trial-prediction"><b>先猜：${d.name}能還原氧化鐵，得到金屬鐵嗎？</b><div>${[[true,'能，能拿走氧化鐵的氧'],[false,'不能，氧仍留在氧化鐵中']].map(([v,label])=>`<button type="button" data-iron-predict="${v}" aria-pressed="${prediction===v}" ${state.phase!=='ready'?'disabled':''}>${label}</button>`).join('')}</div><small>${typeof prediction==='boolean'?'你的預測已留下。加熱後用觀察檢查。':'先選一個預測，再進行這次實驗。'}</small></div>
 <div class="iron-affinity-scene" data-phase="${state.phase}" data-can="${d.canReduce}"><figure><figcaption>加熱前 · 氧化鐵 ＋ ${d.name}</figcaption>${sampleDish(id,false)}</figure><div class="iron-oxygen-direction"><b>${running?'加熱觀察中…':done?(d.canReduce?'氧移到'+d.name:'氧沒有被帶走'):'比較氧的去向'}</b><div>${[0,1,2].map(i=>`<span class="affinity-oxygen" style="--i:${i}">O</span>`).join('')}</div><span>${done&&!d.canReduce?'留在氧化鐵中':'→'}</span></div><figure><figcaption>${done?'加熱後 · 冷卻外觀':'等待加熱後比較'}</figcaption>${done?sampleDish(id,true):'<div class="iron-trial-wait">？</div>'}</figure></div>
 <div class="iron-trial-actions"><button type="button" class="primary" data-iron-heat ${state.phase!=='ready'||typeof prediction!=='boolean'?'disabled':''}>${running?'加熱中…':'加熱，看看結果'}</button><button type="button" class="text-button" data-iron-retry ${running?'disabled':''}>重新預測這一份</button></div>
 <div class="iron-trial-result" role="status">${done?`<b>${correct?'✓ 觀察支持這次預測':'觀察和預測不同，再看氧去了哪裡'}</b><p>${d.canReduce?`${d.name}的對氧活性比鐵大，在本模型的高溫條件下，能使氧化鐵失去氧，得到金屬鐵。`:`${d.name}的對氧活性比鐵小，在本模型的比較條件下，不能把氧化鐵還原成金屬鐵。在這次固定條件下，沒有觀察到金屬鐵形成。`}</p><div class="iron-trial-pair"><span>${d.canReduce?'氧化鐵失去氧 → 被還原':'氧化鐵仍保有氧'}</span><span>${d.canReduce?d.name+'得到氧 → 被氧化':d.name+'沒有拿走氧化鐵的氧'}</span></div><p class="iron-trial-equation">${d.canReduce?d.equation+'（合適高溫）':'未出現將氧化鐵還原成金屬鐵的奪氧反應'}</p>`:running?'正在加熱與比較，請觀察前後的差別。':'這裡會留下觀察結果與氧化、還原的兩邊。'}</div>
 ${Object.keys(state.results).length===6?'<div class="iron-six-summary"><b>把六份結果放在一起</b><p>本模型中，碳、鋅、鉻能帶走氧化鐵的氧；錫、鉛、銅未能取回金屬鐵。</p><strong>C ＞ Zn ＞ Cr ＞ Fe ＞ Sn ＞ Pb ＞ Cu</strong><small>這是本課的對氧活性比較；實際還原還要看氧化物與反應條件。</small></div>':''}
 <details class="iron-trial-records" ${Object.keys(state.results).length?'open':''}><summary>已做的預測與觀察</summary><table><thead><tr><th>材料</th><th>原先預測</th><th>觀察：能否取回鐵</th><th>對氧活性線索</th></tr></thead><tbody>${Object.entries(ironCandidates).filter(([k])=>state.results[k]).map(([k,v])=>`<tr><th>${v.name} ${k}</th><td>${state.predictions[k]===true?'能':state.predictions[k]===false?'不能':'未保存'}</td><td>${v.canReduce?'能，氧化鐵失氧':'不能，沒有得到金屬鐵'}</td><td>${k} ${v.canReduce?'＞':'＜'} Fe</td></tr>`).join('')}</tbody></table></details>
 <p class="iron-trial-model">高溫螢幕模型，僅供比較奪氧方向，非實驗操作指引。活性是相對比較；氧化物種類、溫度與氣體組成都會影響實際結果。省略熔化、揮發與中間反應；碳的含氧產物以 CO₂ 表示總反應，實際亦可能形成 CO。外觀與氧符號只示意物質去向。</p><details class="iron-trial-sources"><summary>比較原則與模型依據</summary><p><a href="https://edu.rsc.org/experiments/the-reactivity-of-iron/1779.article" target="_blank" rel="noopener">RSC：金屬與金屬氧化物的奪氧方向</a> · <a href="https://vrchemistry.chem.ox.ac.uk/nonmetals/lecture3/ellingham.html" target="_blank" rel="noopener">牛津大學：氧化物穩定性與溫度</a></p><p>六種材料沿用本課的元素活性表；本模型用來預測並比較奪氧方向，不能把活性表當作任何溫度、氣氛下的反應保證。</p></details></section>`;
 root.querySelectorAll('[data-iron-candidate]').forEach(b=>b.onclick=()=>{runId++;chooseIronTrial(state,b.dataset.ironCandidate);save();render();});
 root.querySelectorAll('[data-iron-predict]').forEach(b=>b.onclick=()=>{predictIronTrial(state,b.dataset.ironPredict==='true');save();render();});
 root.querySelector('[data-iron-heat]').onclick=()=>{if(!beginIronTrial(state))return;const token=++runId,selected=state.selected;render();ctx.delay(()=>{if(!alive||runId!==token||state.selected!==selected)return;finishIronTrial(state);ctx.record('iron-'+selected);save();render();},3000);};
 root.querySelector('[data-iron-retry]').onclick=()=>{runId++;delete state.predictions[state.selected];state.phase='ready';save();render();};
 }
 render();ctx.onCleanup(()=>{alive=false;runId++;});
}
